<?php require __DIR__.'/includes/bootstrap.php';require_permission('brands.manage');$pageTitle='Brands';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$campaign=trim($_POST['campaign_ids']??'');if($name==='')throw new RuntimeException('Brand name is required.');if($campaign!==''&&!preg_match('/^[0-9,\s]+$/',$campaign))throw new RuntimeException('Campaign IDs must be comma-separated numbers.');$campaign=normalize_ids($campaign);$logo=null;if(!empty($_FILES['logo']['name'])){$f=$_FILES['logo'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024)throw new RuntimeException('Logo upload failed or exceeds 2 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new RuntimeException('Logo must be PNG, JPEG, or WebP.');$logo=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/brands/'.$logo))throw new RuntimeException('Unable to save logo.');}if($id){$q=db()->prepare('UPDATE brands SET name=?,campaign_ids=?,logo=COALESCE(?,logo),updated_at=NOW() WHERE id=?');$q->execute([$name,$campaign,$logo,$id]);}else{$q=db()->prepare('INSERT INTO brands(name,campaign_ids,logo,is_active,created_at,updated_at) VALUES(?,?,?,1,NOW(),NOW())');$q->execute([$name,$campaign,$logo]);$id=(int)db()->lastInsertId();}flash('success','Brand saved.');audit('brand_saved','brand_id='.$id);redirect('brands.php');}elseif($action==='toggle'){$id=(int)$_POST['id'];db()->prepare('UPDATE brands SET is_active=IF(is_active=1,0,1),updated_at=NOW() WHERE id=?')->execute([$id]);flash('success','Brand status updated.');redirect('brands.php');}}catch(Throwable $e){$error=$e->getMessage();}}$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM brands WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$brands=db()->query('SELECT * FROM brands ORDER BY name')->fetchAll();require __DIR__.'/includes/header.php';?><div class="section-title"><h1>Brand Management</h1></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="panel"><h2><?=$edit?'Edit brand':'Add brand'?></h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0)?>"><div class="field"><label>Brand name</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label>Campaign IDs</label><input name="campaign_ids" required value="<?=e($edit['campaign_ids']??'')?>" placeholder="151,150,149"></div><div class="field"><label>Logo (PNG/JPEG/WebP, max 2 MB)</label><input type="file" name="logo" accept="image/png,image/jpeg,image/webp"></div><button>Save brand</button> <?php if($edit):?><a class="btn secondary" href="brands.php">Cancel</a><?php endif;?></form></section><section class="panel"><h2>Brands</h2><div class="table-wrap"><table><thead><tr><th>Logo</th><th>Name</th><th>Campaign IDs</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($brands as $b):?><tr><td><?php if($b['logo']):?><img src="uploads/brands/<?=e($b['logo'])?>" alt="" width="48"><?php endif;?></td><td><?=e($b['name'])?></td><td><?=e($b['campaign_ids'])?></td><td><?=$b['is_active']?'Active':'Inactive'?></td><td><a href="brands.php?edit=<?=(int)$b['id']?>">Edit</a> <form method="post" class="inline"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><button class="secondary"><?=$b['is_active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;?></tbody></table></div><p class="help">Brands are deactivated, not permanently deleted, to preserve historical context.</p></section><?php require __DIR__.'/includes/footer.php'; ?>